function txt(v){return String(v==null?'':v)}
function esc(v){return txt(v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function nrm(v){try{return txt(v).toLocaleLowerCase('nl-NL').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\p{L}\p{N}]+/gu,' ').trim().replace(/\s+/g,' ')}catch(e){return txt(v).toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}}
function byId(x){return D.getElementById(x)}
function modeNow(){try{return txt(mode||'learn')}catch(e){return txt(W.mode||'learn')}}
function setModeRaw(v){try{mode=v}catch(e){W.mode=v}}
function read(k,d){try{var v=localStorage.getItem(P+k);return v==null?d:JSON.parse(v)}catch(e){return d}}
function write(k,v){try{localStorage.setItem(P+k,JSON.stringify(v))}catch(e){}return v}
function notify(v){try{(W.gold||W.msg||function(){})(v)}catch(e){}}
function activeTab(){try{if(typeof W.setActiveTab==='function')W.setActiveTab()}catch(e){}try{D.querySelectorAll('.tabBtn').forEach(function(b){b.classList.toggle('active',b.id==='tabEbook')})}catch(e){}}
function allSources(){var a=[];try{if(typeof W.allSources==='function')a=W.allSources()||[]}catch(e){}try{if(!a.length&&typeof allSources==='function')a=allSources()||[]}catch(e){}try{if(!a.length)(W.LEXLINGO_PACKS||[]).forEach(function(p){a=a.concat(p.sources||[])})}catch(e){}return Array.isArray(a)?a:[]}
function catOf(x){return txt(x&&(x.cat||x.source||x.__origCat)||'Genel')}
function isTraffic(c){return /trafik|verkeer|rijbewij|cbr/.test(nrm(c))}
function isLife(c){return /hollanda rehberi|hollanda ozeti|okul secimi|tuketici egilimleri|nederland|holland|knm|inburger|school|consument/.test(nrm(c))}
function legalCategory(c){return /kuran|kur an|incil|bijbel|bible|grondwet|evrm|wetboek|burgerlijk|straf|strafvordering|bestuursrecht|rechtsvordering|rijbewij|wegenverkeer|verkeer|trafik|migr|goc|vreemdeling|nationaliteit|nederlanderschap|holland|nederland|knm|inburger|okul|school|tuketici|consument|financieel|belasting|arbeid|handelsregister|recht|hukuk|kanun|mevzuat/.test(nrm(c))}
function cloneGroups(){var g={};Object.keys(CUSTOM).forEach(function(k){g[k]=CUSTOM[k].slice()});return g}
function questionEntries(){var d=W.LEX_CURRICULUM_DATA||{},a=Array.isArray(d.questions)?d.questions:[];return a.map(function(q,i){var o=q.options||{},opts=Object.keys(o).map(function(k){return k+') '+txt(o[k])}).join(' · ');return {id:'v122-knm-'+(q.id||i),ref:(q.topic_title||'KNM')+' • '+(q.num||i+1),nl:txt(q.question)+(opts?'\n'+opts:'')+'\nAntwoord: '+txt(q.answer||''),tr:txt(q.answer_tr||q.tr||''),en:txt(q.answer_en||q.en||''),source:'KNM'}})}
var GROUP_CACHE=null;function buildGroups(){if(GROUP_CACHE)return GROUP_CACHE;var g=cloneGroups(),life=[],trafficLaw=[];allSources().forEach(function(s){var c=catOf(s);if(!legalCategory(c))return;if(isTraffic(c))trafficLaw.push(s);else if(isLife(c))life.push(s);else (g[c]||(g[c]=[])).push(s)});if(trafficLaw.length)g['Trafik • Mevzuat']=trafficLaw;if(life.length)g['B1 Yaşam • Uygulama Kaynakları']=life;var q=questionEntries();if(q.length)g['B1 Yaşam • KNM Soru Arşivi']=q;GROUP_CACHE=g;return GROUP_CACHE}
