function groupClass(k){if(k.indexOf('Trafik •')===0)return 'Trafik ve Ehliyet';if(k.indexOf('B1 Yaşam •')===0)return 'B1 Yaşam Hollandacası';if(k.indexOf('B1 Okuma •')===0)return 'B1 Okuma';if(k.indexOf('Dinleme •')===0)return 'Dinleme';if(k.indexOf('Konuşma •')===0)return 'Konuşma';return 'Mevcut E-kitaplar'}
var ORDER=['B1 Okuma','Dinleme','Konuşma','B1 Yaşam Hollandacası','Trafik ve Ehliyet','Mevcut E-kitaplar'];
function sortedKeys(g){return Object.keys(g).sort(function(a,b){var ga=groupClass(a),gb=groupClass(b),ia=ORDER.indexOf(ga),ib=ORDER.indexOf(gb);if(ia!==ib)return ia-ib;return a.localeCompare(b,'tr')})}
function optionsHtml(keys,g,sel){var out='',last='';keys.forEach(function(k){var cl=groupClass(k);if(cl!==last){if(last)out+='</optgroup>';out+='<optgroup label="'+esc(cl)+'">';last=cl}out+='<option value="'+esc(k)+'" '+(k===sel?'selected':'')+'>'+esc(k)+' ('+(g[k]||[]).length+')</option>'});if(last)out+='</optgroup>';return out}
