function groupStats(keys,g,name){var ks=keys.filter(function(k){return groupClass(k)===name}),items=ks.reduce(function(n,k){return n+(g[k]||[]).length},0);return {sections:ks.length,items:items}}
function railHtml(keys,g,current){var cur=groupClass(current);return '<div class="lexV125Rail">'+ORDER.map(function(name){var z=groupStats(keys,g,name);if(!z.sections)return '';return '<button class="'+(name===cur?'on':'')+'" onclick="lexV125OpenMenu(\''+esc(name)+'\')">'+groupIcon(name)+' '+esc(name)+'</button>'}).join('')+'</div>'}
function menuChipsHtml(keys,g){return '<button class="'+(MENU_UI.group==='ALL'?'on':'')+'" onclick="lexV125MenuGroup(\'ALL\')">Tümü</button>'+ORDER.map(function(name){var z=groupStats(keys,g,name);if(!z.sections)return '';return '<button class="'+(MENU_UI.group===name?'on':'')+'" onclick="lexV125MenuGroup(\''+esc(name)+'\')">'+groupIcon(name)+' '+esc(name)+'</button>'}).join('')}
function drawerHtml(keys,g,sel){var blocks=ORDER.map(function(name){var ks=keys.filter(function(k){return groupClass(k)===name});if(!ks.length)return '';var count=ks.reduce(function(n,k){return n+(g[k]||[]).length},0);return '<section class="lexV125MenuGroup" data-menu-group="'+esc(name)+'"><h3>'+groupIcon(name)+' '+esc(name)+'<span>'+ks.length+' bölüm · '+count+' içerik</span></h3>'+ks.map(function(k){var items=(g[k]||[]).length,pages=Math.max(1,Math.ceil(items/pageSize()));return '<button class="lexV125MenuSection '+(k===sel?'current':'')+'" data-menu-label="'+esc(nrm(k+' '+name))+'" data-menu-group-name="'+esc(name)+'" onclick="lexV122EbookChoose(\''+esc(k)+'\')"><div><b>'+esc(k)+'</b><small>'+items+' içerik · '+pages+' sayfa</small></div><span>›</span></button>'}).join('')+'</section>'}).join('');return '<div class="lexV125Drawer" id="lexV125Drawer" aria-hidden="true"><div class="lexV125Shade" onclick="lexV125CloseMenu()"></div><aside class="lexV125Panel" role="dialog" aria-label="E-kitap içindekiler"><div class="lexV125PanelHead"><div><b>İçindekiler</b><small>Arayın, bölümü seçin ve kaldığınız yerden devam edin</small></div><button class="lexV125IconBtn" onclick="lexV125CloseMenu()" aria-label="Menüyü kapat">×</button></div><label class="lexV125Search"><input id="lexV125Search" type="search" placeholder="Bölüm veya konu ara..." oninput="lexV125MenuSearch(this.value)"><span>⌕</span></label><div class="lexV125MenuChips">'+menuChipsHtml(keys,g)+'</div><div class="lexV125MenuScroll">'+blocks+'<div class="lexV125MenuEmpty" id="lexV125MenuEmpty">Aramayla eşleşen bölüm bulunamadı.</div></div></aside></div>'}
function applyMenuFilter(){var root=byId('lexV125Drawer');if(!root)return;var q=nrm(MENU_UI.query),group=MENU_UI.group,visible=0;root.querySelectorAll('.lexV125MenuGroup').forEach(function(box){var boxGroup=box.getAttribute('data-menu-group')||'',inGroup=group==='ALL'||boxGroup===group,inside=0;box.querySelectorAll('.lexV125MenuSection').forEach(function(btn){var ok=inGroup&&(!q||(btn.getAttribute('data-menu-label')||'').indexOf(q)>=0);btn.style.display=ok?'grid':'none';if(ok){inside++;visible++}});box.style.display=inside?'block':'none'});var empty=byId('lexV125MenuEmpty');if(empty)empty.style.display=visible?'none':'block';root.querySelectorAll('.lexV125MenuChips button').forEach(function(b){var t=nrm(b.textContent),target=nrm(group==='ALL'?'Tümü':group);b.classList.toggle('on',t.indexOf(target)>=0||target.indexOf(t)>=0)})}
function renderEbook122(){installCss();setModeRaw('ebook');activeTab();D.body.classList.remove('g121Active');D.body.classList.add('lexV122EbookActive');D.body.classList.remove('lexV125DrawerOpen');var v=byId('view'),g=buildGroups(),keys=sortedKeys(g);if(!v)return;var s=state();if(!s.category||!g[s.category])s.category=keys[0]||'';var a=g[s.category]||[],n=Math.max(1,Math.ceil(a.length/pageSize())),p=Math.max(0,Math.min(Number(s.pages[s.category])||0,n-1));s.pages[s.category]=p;write('v122Ebook',s);var part=a.slice(p*pageSize(),p*pageSize()+pageSize());var body=part.map(function(x,i){return '<article class="lexV119BookArticle">'+imageHtml(x)+'<h4>'+esc(x.ref||x.src||('Metin '+(p*pageSize()+i+1)))+'</h4>'+bookLang('nl','Nederlands',x.nl,false)+bookLang('en','English',x.en,false)+bookLang('tr','Türkçe',x.tr,false)+bookLang('ar','العربية',x.ar,true)+bookLang('ru','Русский',x.ru,false)+(x.source?'<div class="lexV122Source">Kaynak: '+esc(x.source)+'</div>':'')+'</article>'}).join('')||'<p>Bu bölümde içerik bulunamadı.</p>';var curGroup=groupClass(s.category),pct=Math.round((p+1)/n*100);v.innerHTML='<section class="card lexV119Ebook lexV122Ebook"><div class="lexV125Header"><button class="lexV125IconBtn" onclick="lexV125OpenMenu()" aria-label="E-kitap menüsünü aç">☰</button><div class="lexV125Brand"><b>E-kitap Kütüphanesi</b><span>'+groupIcon(curGroup)+' '+esc(curGroup)+'</span></div><button class="lexV125IconBtn" onclick="lexV125OpenMenu();setTimeout(function(){var x=document.getElementById(\'lexV125Search\');if(x)x.focus()},80)" aria-label="Bölüm ara">⌕</button></div><div class="lexV125SectionBar"><button class="lexV125SectionBtn" onclick="lexV125OpenMenu(\''+esc(curGroup)+'\')"><b>'+esc(s.category)+'</b><small>'+a.length+' içerik · '+n+' sayfa · bölüm değiştirmek için dokunun</small></button><button class="ghost lexV125ReadBtn" onclick="lexV122EbookSpeak(\'nl\',this)">🔊 Oku</button></div>'+railHtml(keys,g,s.category)+'<div class="lexV125Progress"><i style="width:'+pct+'%"></i></div><div class="lexV119Book"><div class="lexV119BookTitle">'+esc(s.category)+'</div><div class="lexV119PageCorner">'+(p+1)+' / '+n+'</div><div class="lexV119BookPage" data-lex-v122-swipe="ebook">'+body+'</div></div><div class="row3"><button class="ghost" onclick="lexV122EbookSpeak(\'en\',this)">🔊 EN</button><button class="ghost" onclick="lexV122EbookSpeak(\'tr\',this)">🔊 TR</button><button class="ghost" onclick="lexV122EbookSpeak(\'ar\',this)">🔊 AR</button></div><div class="lexV125PageNav"><button class="ghost" onclick="lexV122EbookStep(-1)">‹ Önceki</button><label class="lexV125PageJump"><input type="range" min="1" max="'+n+'" value="'+(p+1)+'" '+(n<=1?'disabled':'')+' oninput="lexV125RangeLabel(this)" onchange="lexV125EbookJump(this.value)"><b>'+(p+1)+' / '+n+'</b></label><button class="ghost" onclick="lexV122EbookStep(1)">Sonraki ›</button></div>'+drawerHtml(keys,g,s.category)+'</section>';try{W.scrollTo(0,0)}catch(e){}}
W.lexV122EbookRender=renderEbook122;
W.lexV122EbookChoose=function(k){var s=state();s.category=txt(k);s.pages[s.category]=0;write('v122Ebook',s);W.lexV125CloseMenu();renderEbook122()};
W.lexV122EbookStep=function(d){var g=buildGroups(),s=state(),a=g[s.category]||[],n=Math.max(1,Math.ceil(a.length/pageSize()));s.pages[s.category]=((Number(s.pages[s.category])||0)+(Number(d)||0)+n)%n;write('v122Ebook',s);renderEbook122()};
W.lexV125RangeLabel=function(x){var b=x&&x.nextElementSibling;if(b)b.textContent=x.value+' / '+x.max};
W.lexV125EbookJump=function(v){var g=buildGroups(),s=state(),a=g[s.category]||[],n=Math.max(1,Math.ceil(a.length/pageSize())),p=Math.max(0,Math.min(n-1,(Number(v)||1)-1));s.pages[s.category]=p;write('v122Ebook',s);renderEbook122()};
W.lexV124EbookExportData=function(){var g=buildGroups(),s=state(),a=g[s.category]||[],p=Number(s.pages[s.category])||0;return {category:s.category,page:p,pageSize:pageSize(),pages:Math.max(1,Math.ceil(a.length/pageSize())),items:a.slice()}};
W.lexV122EbookSpeak=function(c,btn){var g=buildGroups(),s=state(),a=g[s.category]||[],p=Number(s.pages[s.category])||0,part=a.slice(p*pageSize(),p*pageSize()+pageSize()),value=part.map(function(x){return field(x,c)}).filter(Boolean).join(' ');if(!value)return notify('Bu sayfada seçilen dilde metin bulunmuyor.');try{if(typeof W.speak==='function')return W.speak(value,lang(c),'v122ebook-'+c,btn);if(typeof speak==='function')return speak(value,lang(c),'v122ebook-'+c,btn)}catch(e){notify('Seslendirme başlatılamadı.')}};
W.lexV125OpenMenu=function(group){if(group)MENU_UI.group=txt(group);var d=byId('lexV125Drawer');if(!d)return;d.classList.add('open');d.setAttribute('aria-hidden','false');D.body.classList.add('lexV125DrawerOpen');applyMenuFilter()};
W.lexV125CloseMenu=function(){var d=byId('lexV125Drawer');if(d){d.classList.remove('open');d.setAttribute('aria-hidden','true')}D.body.classList.remove('lexV125DrawerOpen')};
W.lexV125MenuGroup=function(group){MENU_UI.group=txt(group||'ALL');applyMenuFilter()};
W.lexV125MenuSearch=function(q){MENU_UI.query=txt(q);applyMenuFilter()};
D.addEventListener('keydown',function(e){if(e.key==='Escape')W.lexV125CloseMenu()},true);
var swipe=null;D.addEventListener('pointerdown',function(e){var n=e.target&&e.target.closest&&e.target.closest('[data-lex-v122-swipe]');if(n)swipe={x:e.clientX,y:e.clientY}},true);D.addEventListener('pointerup',function(e){if(!swipe)return;var d=swipe;swipe=null,dx=e.clientX-d.x,dy=e.clientY-d.y;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.3)W.lexV122EbookStep(dx<0?1:-1)},true);
var baseSet=null,baseRender=null;
function grammarRender(){D.body.classList.remove('lexV122EbookActive');D.body.classList.remove('lexV125DrawerOpen');if(typeof W.lexG121Render==='function')return W.lexG121Render();if(typeof W.lexG121View==='function'){var st={};try{st=(W.lexG121Stats&&W.lexG121Stats().state)||{}}catch(e){}return W.lexG121View(st.view||'home')}}
function routeSet(m){var original=m,key=nrm(m);if(key==='ebook'||key==='e kitap'||key==='e book'){try{W.__lexArchiveMode=false}catch(e){}return renderEbook122()}if(key==='grammar'||key==='paragraph'){try{W.__lexArchiveMode=false}catch(e){}return grammarRender()}D.body.classList.remove('lexV122EbookActive');D.body.classList.remove('lexV125DrawerOpen');return baseSet?baseSet.call(this,original):undefined}
function routeRender(){var key=nrm(modeNow());if(key==='ebook')return renderEbook122();if(key==='grammar'||key==='paragraph')return grammarRender();D.body.classList.remove('lexV122EbookActive');D.body.classList.remove('lexV125DrawerOpen');return baseRender?baseRender.apply(this,arguments):undefined}
function installRoutes(){W.setMode=routeSet;W.render=routeRender;try{setMode=W.setMode;render=W.render}catch(e){}}
function boot(){installCss();if(!baseSet){baseSet=W.setMode;baseRender=W.render}installRoutes();[100,500,1200,3000,5200].forEach(function(ms){setTimeout(installRoutes,ms)});var key=nrm(modeNow());if(key==='ebook')setTimeout(renderEbook122,80);else if(key==='grammar'||key==='paragraph')setTimeout(grammarRender,80)}
if(D.readyState==='loading')D.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
